<?php require_once __DIR__.'/config/auth.php';$pageTitle='Laporan Keuangan';$awal=$_GET['awal']??date('Y-m-01');$akhir=$_GET['akhir']??date('Y-m-d');$s=$pdo->prepare("SELECT COALESCE(SUM(CASE WHEN jenis='pemasukan' THEN nominal ELSE 0 END),0) masuk,COALESCE(SUM(CASE WHEN jenis='pengeluaran' THEN nominal ELSE 0 END),0) keluar FROM transaksi WHERE tanggal BETWEEN ? AND ?");$s->execute([$awal,$akhir]);$sum=$s->fetch();$s=$pdo->prepare("SELECT t.*,k.nama kategori FROM transaksi t JOIN kategori k ON k.id=t.kategori_id WHERE t.tanggal BETWEEN ? AND ? ORDER BY t.tanggal DESC,t.id DESC");$s->execute([$awal,$akhir]);$data=$s->fetchAll();function rpl($n){return 'Rp '.number_format($n,0,',','.');}include __DIR__.'/partials/header.php';?><div class="card p-4 mb-4"><form class="row g-3 align-items-end"><div class="col-md-3"><label>Dari</label><input type="date" name="awal" value="<?=$awal?>" class="form-control"></div><div class="col-md-3"><label>Sampai</label><input type="date" name="akhir" value="<?=$akhir?>" class="form-control"></div><div class="col-md-2"><button class="btn btn-primary">Tampilkan</button></div><div class="col-md-2"><button type="button" onclick="window.print()" class="btn btn-outline-secondary">Cetak</button></div></form></div><div class="row g-3 mb-4"><div class="col-md-4"><div class="card p-3"><div>Pemasukan</div><h3 class="income"><?=rpl($sum['masuk'])?></h3></div></div><div class="col-md-4"><div class="card p-3"><div>Pengeluaran</div><h3 class="expense"><?=rpl($sum['keluar'])?></h3></div></div><div class="col-md-4"><div class="card p-3"><div>Saldo</div><h3 class="balance"><?=rpl($sum['masuk']-$sum['keluar'])?></h3></div></div></div><div class="card p-4"><h5>Laporan <?=date('d/m/Y',strtotime($awal))?> - <?=date('d/m/Y',strtotime($akhir))?></h5><table class="table"><thead><tr><th>Tanggal</th><th>Jenis</th><th>Kategori</th><th>Keterangan</th><th>Nominal</th></tr></thead><tbody><?php foreach($data as $r):?><tr><td><?=$r['tanggal']?></td><td><?=ucfirst($r['jenis'])?></td><td><?=htmlspecialchars($r['kategori'])?></td><td><?=htmlspecialchars($r['keterangan']?:'-')?></td><td><?=rpl($r['nominal'])?></td></tr><?php endforeach;?></tbody></table></div><?php include __DIR__.'/partials/footer.php';?>